(()=>{
 const panel=document.createElement('details');panel.id='flipbook-panel';panel.className='advanced';panel.innerHTML='<summary>Particle textures & flipbooks</summary><p class="animation-intro">Import a transparent PNG or a sheet of animation frames. Frames read left to right, then top to bottom. The image travels inside your project and presets. Use up to 2048 × 2048 pixels and 256 KB.</p>';
 const file=document.createElement('input');file.type='file';file.accept='image/png';file.id='flipbook-file';file.setAttribute('aria-label','Import particle PNG');panel.append(file);const status=document.createElement('p');status.className='animation-intro';status.setAttribute('role','status');panel.append(status);const inputs={};
 for(const [key,label,min,max]of [['columns','Columns',1,16],['rows','Rows',1,16],['fps','Frames per second',1,60]]){const row=document.createElement('label');row.textContent=label;const input=document.createElement('input');input.type='number';input.min=min;input.max=max;input.step=key==='fps'?'any':1;input.id='flipbook-'+key;input.setAttribute('aria-label',label);input.onchange=()=>{if(!input.checkValidity()||!state.flipbook)return;try{const next={...state.flipbook,[key]:input.valueAsNumber};EmberFlipbook.validate(next);state.flipbook=next;persist();status.textContent='Texture saved with this layer.';}catch(e){status.textContent=e.message;}refresh();};row.append(input);panel.append(row);inputs[key]=input;}
 const loopLabel=document.createElement('label');loopLabel.textContent='Loop animation';const loop=document.createElement('input');loop.type='checkbox';loop.id='flipbook-loop';loop.onchange=()=>{state.flipbook.loop=loop.checked;persist();};loopLabel.append(loop);panel.append(loopLabel);const remove=document.createElement('button');remove.textContent='Remove texture';remove.id='flipbook-remove';remove.onclick=()=>{delete state.flipbook;sync();persist();};panel.append(remove);
 file.onchange=async()=>{const selected=file.files[0];if(!selected)return;try{if(selected.size>256*1024)throw Error('Choose a PNG smaller than 256 KB.');const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read image'));reader.readAsDataURL(selected);});const next={image,columns:1,rows:1,fps:12,loop:true};EmberFlipbook.validate(next);const bitmap=await createImageBitmap(selected);bitmap.close();state.flipbook=next;state.renderer='sprite';sync();persist();status.textContent='Texture imported. Set rows and columns for an animation sheet.';}catch(e){status.textContent=e.message;}finally{file.value='';}};
 function refresh(){for(const [key,input]of Object.entries(inputs)){input.value=state.flipbook?.[key]??(key==='fps'?12:1);input.disabled=!state.flipbook;}loop.checked=state.flipbook?.loop??true;loop.disabled=remove.disabled=!state.flipbook;status.textContent=state.flipbook?'Texture saved with this layer.':'No texture: using the selected procedural shape.';}
 $('#animation-panel').before(panel);const previous=sync;sync=()=>{previous();refresh();};refresh();
})();
